const BUNDLE_ID = "pudge-butcher-cr16-v1";
const VERSION = "v1.0";
const ACTOR_NAME = "Пудж, Мясник Междумирья [CR 16] v1.0";
const JOURNAL_NAME = "Памятка: Пудж, Мясник Междумирья v1.0";
const FOLDER_NAME = "Боссы AI Patcher";
const AVATAR = "assets/pudge-avatar.png";
const TOKEN = "assets/pudge-token.png";
const SAVE_DC = 19;
const ENGINE_NAME = "PudgeEngine";

function asset(bundle, localPath) {
  return bundle?.assets?.[localPath] ?? `modules/ai-patcher/inbox/${BUNDLE_ID}/${localPath}`;
}

function clone(data) {
  return foundry.utils.deepClone(data);
}

function activityValues(activities) {
  if (!activities) return [];
  if (activities.contents) return activities.contents;
  if (activities.values) return Array.from(activities.values());
  return Object.values(activities);
}

async function getOrCreateFolder(name, type) {
  const existing = game.folders.find((folder) => folder.type === type && folder.name === name);
  if (existing) return existing;
  return Folder.create({ name, type });
}

function automationFlags(name, command, passes = "[postActiveEffects]ItemMacro") {
  const embedded = {
    name,
    type: "script",
    img: "icons/commodities/hooks/hook-meat-red.webp",
    scope: "global",
    command,
    ownership: { default: CONST.DOCUMENT_OWNERSHIP_LEVELS.OWNER },
    flags: { dnd5e: { itemMacro: true }, "ai-patcher": { bundleId: BUNDLE_ID } }
  };
  return {
    itemacro: { macro: embedded },
    dae: { macro: embedded },
    "midi-qol": { onUseMacroName: `${name},${passes}` }
  };
}

const PUDGE_ENGINE = String.raw`
const macroArgs = typeof args !== "undefined" ? args : [];
const data = macroArgs?.[0] ?? {};
const pass = data.macroPass ?? "";
const workflow = data.workflow ?? globalThis.workflow ?? {};
const sourceItem = item ?? data.item ?? workflow.item;
const sourceActor = actor ?? data.actor ?? workflow.actor;
const sourceName = String(sourceItem?.name ?? "");
const BUNDLE_ID = "pudge-butcher-cr16-v1";
const SAVE_DC = 19;

function num(value, fallback = 0) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function actorEffects(actorDoc) {
  if (!actorDoc?.effects) return [];
  if (Array.isArray(actorDoc.effects.contents)) return actorDoc.effects.contents;
  if (actorDoc.effects.values) return Array.from(actorDoc.effects.values());
  return Array.from(actorDoc.effects);
}

function sourceToken() {
  const macroToken = typeof token !== "undefined" ? token : null;
  const byActor = canvas.tokens?.placeables?.find((candidate) => candidate.actor?.id === sourceActor?.id || candidate.actor?.uuid === sourceActor?.uuid);
  return macroToken ?? workflow.token ?? byActor ?? canvas.tokens?.controlled?.[0];
}

function centerOf(tokenLike) {
  const doc = tokenLike?.document ?? tokenLike;
  const gridSize = canvas.grid?.size ?? canvas.scene?.grid?.size ?? 100;
  return tokenLike?.center ?? {
    x: num(doc?.x) + num(doc?.width, 1) * gridSize / 2,
    y: num(doc?.y) + num(doc?.height, 1) * gridSize / 2
  };
}

function distance(a, b) {
  if (!a || !b) return Infinity;
  try {
    if (globalThis.MidiQOL?.computeDistance) return MidiQOL.computeDistance(a, b, { wallsBlock: false, includeCover: false });
  } catch (_error) {}
  const ac = centerOf(a);
  const bc = centerOf(b);
  const gridSize = canvas.grid?.size ?? canvas.scene?.grid?.size ?? 100;
  const gridDistance = canvas.dimensions?.distance ?? canvas.scene?.grid?.distance ?? 5;
  return Math.hypot(ac.x - bc.x, ac.y - bc.y) / gridSize * gridDistance;
}

function hostileTokensInRange(range) {
  const self = sourceToken();
  if (!self) return [];
  const disposition = self.document?.disposition ?? -1;
  return (canvas.tokens?.placeables ?? []).filter((target) => {
    if (!target.actor || target.id === self.id || target.document?.hidden) return false;
    if (num(target.actor.system?.attributes?.hp?.value, 1) <= 0) return false;
    if ((target.document?.disposition ?? 0) === disposition) return false;
    return distance(self, target) <= range + 0.01;
  });
}

function hasStatus(actorDoc, statuses) {
  const wanted = new Set(statuses);
  return actorEffects(actorDoc).some((effect) => {
    if (effect.disabled) return false;
    if (Array.from(effect.statuses ?? []).some((status) => wanted.has(status))) return true;
    const name = String(effect.name ?? "").toLowerCase();
    return statuses.some((status) => name.includes(status));
  });
}

function failedTargets() {
  return Array.from(workflow.failedSaves ?? []);
}

function hitTargets() {
  return Array.from(workflow.hitTargets ?? []);
}

async function updateHp(actorDoc, delta) {
  if (!actorDoc) return;
  const hp = actorDoc.system?.attributes?.hp ?? {};
  const current = num(hp.value);
  const max = num(hp.max, current);
  const next = Math.max(0, Math.min(max, current + delta));
  await actorDoc.update({ "system.attributes.hp.value": next });
}

async function setTempHp(actorDoc, delta, cap) {
  if (!actorDoc) return;
  const hp = actorDoc.system?.attributes?.hp ?? {};
  const current = num(hp.temp);
  const next = Math.max(current, Math.min(cap, current + delta));
  await actorDoc.update({ "system.attributes.hp.temp": next });
}

async function rollParts(parts, flavor, speakerActor = sourceActor, speakerToken = sourceToken()) {
  const details = [];
  let total = 0;
  for (const part of parts) {
    const roll = await new Roll(part.formula).evaluate();
    total += roll.total;
    details.push({ damage: roll.total, value: roll.total, type: part.type, formula: part.formula, properties: new Set(["mgc", "damage"]) });
    await roll.toMessage({
      speaker: ChatMessage.getSpeaker({ actor: speakerActor, token: speakerToken?.document ?? speakerToken }),
      flavor: flavor + ": " + part.formula + " " + (CONFIG.DND5E.damageTypes[part.type]?.label ?? part.type)
    });
  }
  return { details, total };
}

async function applyDamage(targetToken, details, total, itemDoc = sourceItem) {
  if (!targetToken?.actor || total <= 0) return;
  if (globalThis.MidiQOL?.applyTokenDamage) {
    await MidiQOL.applyTokenDamage(details, total, new Set([targetToken]), itemDoc, new Set(), {
      forceApply: true,
      noConcentrationCheck: false,
      updateOptions: { awaitDamageApplication: true }
    });
    return;
  }
  const hp = targetToken.actor.system?.attributes?.hp ?? {};
  await targetToken.actor.update({ "system.attributes.hp.value": Math.max(0, num(hp.value) - total) });
}

async function applyEffect(targetActor, effectData) {
  if (!targetActor) return;
  const old = actorEffects(targetActor).filter((effect) => effect.getFlag?.("world", effectData.flag));
  if (old.length) await targetActor.deleteEmbeddedDocuments("ActiveEffect", old.map((effect) => effect.id));
  await targetActor.createEmbeddedDocuments("ActiveEffect", [{
    name: effectData.name,
    img: effectData.img ?? sourceItem?.img ?? "icons/commodities/hooks/hook-meat-red.webp",
    origin: sourceItem?.uuid,
    duration: effectData.duration ?? { rounds: 1, turns: 1 },
    statuses: effectData.statuses ?? [],
    changes: effectData.changes ?? [],
    description: effectData.description ?? "",
    flags: {
      "ai-patcher": { bundleId: BUNDLE_ID },
      world: { [effectData.flag]: true, ...(effectData.world ?? {}) },
      dae: effectData.dae ?? {}
    }
  }]);
}

async function rollSave(target, ability, dc, flavor) {
  if (!target?.actor) return 0;
  try {
    const rolls = await target.actor.rollSavingThrow(
      { ability, target: dc },
      { configure: false },
      { data: { speaker: ChatMessage.getSpeaker({ actor: target.actor, token: target.document }), flavor } }
    );
    return num(rolls?.[0]?.total);
  } catch (_error) {
    const mod = num(target.actor.system?.abilities?.[ability]?.save ?? target.actor.system?.abilities?.[ability]?.mod);
    const roll = await new Roll("1d20 + @mod", { mod }).evaluate();
    await roll.toMessage({ speaker: ChatMessage.getSpeaker({ actor: target.actor, token: target.document }), flavor });
    return roll.total;
  }
}

function pullToAdjacent(target) {
  const self = sourceToken();
  if (!self || !target?.document) return;
  const gridSize = canvas.grid?.size ?? canvas.scene?.grid?.size ?? 100;
  const selfDoc = self.document;
  const targetDoc = target.document;
  const sx = num(selfDoc.x);
  const sy = num(selfDoc.y);
  const sw = Math.max(1, num(selfDoc.width, 1));
  const sh = Math.max(1, num(selfDoc.height, 1));
  const tw = Math.max(1, num(targetDoc.width, 1));
  const th = Math.max(1, num(targetDoc.height, 1));
  const candidates = [];
  for (let ix = -tw; ix <= sw; ix += 1) {
    candidates.push({ x: sx + ix * gridSize, y: sy - th * gridSize });
    candidates.push({ x: sx + ix * gridSize, y: sy + sh * gridSize });
  }
  for (let iy = 0; iy < sh; iy += 1) {
    candidates.push({ x: sx - tw * gridSize, y: sy + iy * gridSize });
    candidates.push({ x: sx + sw * gridSize, y: sy + iy * gridSize });
  }
  const current = { x: num(targetDoc.x), y: num(targetDoc.y) };
  candidates.sort((a, b) => Math.hypot(a.x - current.x, a.y - current.y) - Math.hypot(b.x - current.x, b.y - current.y));
  targetDoc.update(candidates[0]);
}

async function useNamedItem(name) {
  const nextItem = sourceActor?.items?.find?.((candidate) => candidate.name === name);
  if (!nextItem) return ui.notifications?.warn("Пудж: не найдена способность " + name + ".");
  if (globalThis.MidiQOL?.completeItemUse) return MidiQOL.completeItemUse(nextItem, {}, {});
  if (nextItem.use) return nextItem.use();
  return ui.notifications?.warn("Пудж: этот лист не поддерживает автоматический запуск " + name + ".");
}

function damageTypesOf(damageItem) {
  const details = damageItem?.rawDamageDetail ?? damageItem?.damageDetail ?? [];
  return details.map((entry) => ({
    type: String(entry.type ?? ""),
    value: Math.max(0, num(entry.value ?? entry.damage))
  }));
}

async function applyFleshShield() {
  const targetActor = actor ?? data.actor;
  if (!targetActor?.getFlag?.("world", "pudgeButcher")) return;
  const damageItem = data.damageItem ?? data.ditem ?? workflow.damageItem;
  if (!damageItem) return;
  const incoming = Math.max(0, num(damageItem.hpDamage) + num(damageItem.tempDamage));
  if (!incoming) return;
  const itemName = String((data.item ?? workflow.item)?.name ?? "");
  if (/Гниение/.test(itemName) && workflow.actor?.uuid === targetActor.uuid) return;
  const entries = damageTypesOf(damageItem);
  const reducible = entries.reduce((sum, entry) => sum + (entry.type === "force" ? 0 : entry.value), 0);
  if (!reducible) return;
  const reduction = Math.min(20, reducible, incoming);
  if (!reduction) return;
  if (globalThis.MidiQOL?.modifyDamageBy) {
    MidiQOL.modifyDamageBy({ damageItem, value: -reduction, type: "none", reason: "Щит плоти Пуджа" });
  } else {
    damageItem.hpDamage = Math.max(0, num(damageItem.hpDamage) - reduction);
    damageItem.details ??= [];
    damageItem.details.push("Щит плоти Пуджа: -" + reduction);
  }
}

function actorsWithDismemberEffect(sourceUuid) {
  const result = [];
  for (const actorDoc of game.actors.contents) {
    const effect = actorEffects(actorDoc).find((candidate) => candidate.getFlag?.("world", "pudgeDismembered") && candidate.getFlag?.("world", "pudgeDismemberSource") === sourceUuid);
    if (effect) result.push({ actor: actorDoc, effect });
  }
  for (const scene of game.scenes.contents) {
    for (const tokenDoc of scene.tokens.contents) {
      const actorDoc = tokenDoc.actor;
      if (!actorDoc) continue;
      const effect = actorEffects(actorDoc).find((candidate) => candidate.getFlag?.("world", "pudgeDismembered") && candidate.getFlag?.("world", "pudgeDismemberSource") === sourceUuid);
      if (effect && !result.some((entry) => entry.actor.uuid === actorDoc.uuid)) result.push({ actor: actorDoc, effect });
    }
  }
  return result;
}

async function cancelDismember(sourceActorDoc, reason) {
  if (!sourceActorDoc?.getFlag?.("world", "pudgeButcher")) return;
  const channel = actorEffects(sourceActorDoc).filter((effect) => effect.getFlag?.("world", "pudgeDismemberChannel"));
  if (!channel.length) return;
  const sourceUuid = sourceActorDoc.uuid;
  const targets = actorsWithDismemberEffect(sourceUuid);
  for (const entry of targets) await entry.actor.deleteEmbeddedDocuments("ActiveEffect", [entry.effect.id]);
  await sourceActorDoc.deleteEmbeddedDocuments("ActiveEffect", channel.map((effect) => effect.id));
  await ChatMessage.create({
    speaker: ChatMessage.getSpeaker({ actor: sourceActorDoc }),
    content: "<p><strong>Расчленение прервано.</strong> " + (reason ?? "Пудж потерял контроль над жертвой.") + "</p>"
  });
}

async function finishDismember(sourceActorDoc) {
  if (!sourceActorDoc?.getFlag?.("world", "pudgeButcher")) return;
  const channel = actorEffects(sourceActorDoc).filter((effect) => effect.getFlag?.("world", "pudgeDismemberChannel"));
  if (!channel.length) return;
  if (hasStatus(sourceActorDoc, ["stunned", "paralyzed", "incapacitated", "unconscious", "dead"])) {
    await cancelDismember(sourceActorDoc, "Пудж был оглушён или выведен из строя до начала своего хода.");
    return;
  }
  const self = canvas.tokens?.placeables?.find((candidate) => candidate.actor?.uuid === sourceActorDoc.uuid);
  const targets = actorsWithDismemberEffect(sourceActorDoc.uuid);
  for (const entry of targets) {
    const targetToken = canvas.tokens?.placeables?.find((candidate) => candidate.actor?.uuid === entry.actor.uuid);
    if (!targetToken) continue;
    const roll = await rollParts([{ formula: "5d10", type: "necrotic" }], "Финальный рывок Расчленения", sourceActorDoc, self);
    await applyDamage(targetToken, roll.details, roll.total);
    await updateHp(sourceActorDoc, Math.floor(roll.total / 2));
    await entry.actor.deleteEmbeddedDocuments("ActiveEffect", [entry.effect.id]);
  }
  await sourceActorDoc.deleteEmbeddedDocuments("ActiveEffect", channel.map((effect) => effect.id));
}

function interruptedEffect(effect) {
  const statuses = Array.from(effect?.statuses ?? []);
  if (statuses.some((status) => ["stunned", "paralyzed", "incapacitated", "unconscious", "dead"].includes(status))) return true;
  const name = String(effect?.name ?? "").toLowerCase();
  return ["stunned", "paralyzed", "incapacitated", "unconscious"].some((status) => name.includes(status));
}

function installHooks() {
  if (globalThis.__pudgeButcherHooksV1) return;
  globalThis.__pudgeButcherHooksV1 = [];
  const add = (hookName, fn) => globalThis.__pudgeButcherHooksV1.push({ hookName, id: Hooks.on(hookName, fn) });
  add("updateActor", async (actorDoc, changed) => {
    const nextHp = foundry.utils.getProperty(changed, "system.attributes.hp.value");
    if (!Number.isFinite(Number(nextHp)) || Number(nextHp) > 0) return;
    globalThis.__pudgeButcherDeathKeysV1 ??= new Set();
    const key = actorDoc.uuid + ":" + (game.combat?.id ?? "no-combat") + ":" + (game.combat?.round ?? 0) + ":" + (game.combat?.turn ?? 0);
    if (globalThis.__pudgeButcherDeathKeysV1.has(key)) return;
    globalThis.__pudgeButcherDeathKeysV1.add(key);
    const deadToken = canvas.tokens?.placeables?.find((candidate) => candidate.actor?.uuid === actorDoc.uuid);
    if (!deadToken) return;
    const dismember = actorEffects(actorDoc).find((effect) => effect.getFlag?.("world", "pudgeDismembered"));
    const dismemberSource = dismember?.getFlag?.("world", "pudgeDismemberSource");
    for (const pudgeToken of canvas.tokens?.placeables ?? []) {
      if (!pudgeToken.actor?.getFlag?.("world", "pudgeButcher")) continue;
      if (pudgeToken.actor.uuid === actorDoc.uuid) continue;
      if (distance(pudgeToken, deadToken) > 30) continue;
      await setTempHp(pudgeToken.actor, 10, 60);
      if (dismemberSource && pudgeToken.actor.uuid === dismemberSource) await updateHp(pudgeToken.actor, 20);
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: pudgeToken.actor, token: pudgeToken.document }),
        content: "<p><strong>Щит плоти.</strong> Смерть рядом добавляет Пуджу 10 временных хитов, максимум 60." + (dismemberSource === pudgeToken.actor.uuid ? " Жертва погибла от Расчленения: Пудж дополнительно восстанавливает 20 хитов." : "") + "</p>"
      });
    }
  });
  add("updateCombat", async (combat, changed) => {
    if (!("turn" in changed) && !("round" in changed)) return;
    const actorDoc = combat?.combatant?.actor;
    if (actorDoc?.getFlag?.("world", "pudgeButcher")) {
      try {
        await finishDismember(actorDoc);
        if (actorDoc.getFlag("world", "pudgeRotActive")) await applyRotPulse(actorDoc);
      } catch (error) {
        console.error("PudgeEngine updateCombat failed", error);
      }
    }
  });
  const watchEffect = async (effect) => {
    const actorDoc = effect?.parent;
    if (actorDoc?.getFlag?.("world", "pudgeButcher") && interruptedEffect(effect)) {
      try { await cancelDismember(actorDoc, "Пудж получил состояние, которое прерывает удержание."); }
      catch (error) { console.error("PudgeEngine interrupt failed", error); }
    }
  };
  add("createActiveEffect", watchEffect);
  add("updateActiveEffect", watchEffect);
}

async function applyRotPulse(actorDoc = sourceActor) {
  if (!actorDoc) return;
  const previousActor = sourceActor;
  const self = canvas.tokens?.placeables?.find((candidate) => candidate.actor?.uuid === actorDoc.uuid) ?? sourceToken();
  if (!self) return ui.notifications?.warn("Пудж: нужен токен на сцене для Гниения.");
  const enemies = hostileTokensInRange(15);
  for (const target of enemies) {
    const save = await rollSave(target, "con", SAVE_DC, "Гниение Пуджа: спасбросок Телосложения СЛ " + SAVE_DC);
    const poison = await rollParts([{ formula: "4d8", type: "necrotic" }], "Гниение Пуджа", actorDoc, self);
    const amount = save >= SAVE_DC ? Math.floor(poison.total / 2) : poison.total;
    const details = [{ damage: amount, value: amount, type: "necrotic", formula: "4d8", properties: new Set(["mgc", "damage"]) }];
    await applyDamage(target, details, amount);
    if (save < SAVE_DC) {
      await applyEffect(target.actor, {
        name: "Гниение Пуджа",
        flag: "pudgeRotPoisoned",
        statuses: ["poisoned"],
        duration: { rounds: 1, turns: 1 },
        description: "<p>Цель задыхается в облаке гнилого мяса. Она отравлена до начала следующего хода Пуджа.</p>"
      });
    }
  }
  await updateHp(actorDoc, -9);
  await ChatMessage.create({
    speaker: ChatMessage.getSpeaker({ actor: actorDoc, token: self?.document }),
    content: "<p><strong>Гниение.</strong> Пудж получает <strong>9 некротического урона</strong> от собственной ауры. Щит плоти этот урон не снижает.</p>"
  });
  return previousActor;
}

installHooks();

if (pass === "isDamaged") {
  await applyFleshShield();
  return;
}

if (pass !== "postActiveEffects") return;

if (/Мультиатака/.test(sourceName)) {
  await ChatMessage.create({
    speaker: ChatMessage.getSpeaker({ actor: sourceActor, token: sourceToken()?.document }),
    content: "<p><strong>Мультиатака.</strong> Пудж выполняет две атаки Мясницким тесаком и один Укус по текущей выбранной цели.</p>"
  });
  await useNamedItem("Мясницкий тесак");
  await useNamedItem("Мясницкий тесак");
  await useNamedItem("Укус");
  return;
}

if (/Мясной крюк|Крюк из дыма/.test(sourceName)) {
  for (const target of hitTargets()) {
    if (target.document?.width <= 3 && target.document?.height <= 3) pullToAdjacent(target);
    await applyEffect(target.actor, {
      name: "Зацеплен крюком Пуджа",
      flag: "pudgeHooked",
      statuses: ["restrained"],
      duration: { rounds: 1, turns: 1 },
      description: "<p>Крюк пробил тело и цепь тянет цель к Пуджу. Цель удержана до конца своего следующего хода.</p>"
    });
  }
  return;
}

if (/Мясницкий тесак/.test(sourceName)) {
  for (const target of hitTargets()) {
    if (!hasStatus(target.actor, ["restrained", "grappled"])) continue;
    const extra = await rollParts([{ formula: "2d8", type: "slashing" }], "Мясницкий тесак: цель удержана");
    await applyDamage(target, extra.details, extra.total);
  }
  return;
}

if (/Укус/.test(sourceName)) {
  for (const target of hitTargets()) {
    const hp = target.actor?.system?.attributes?.hp ?? {};
    if (num(hp.value) <= Math.floor(num(hp.max, 1) / 2)) {
      await updateHp(sourceActor, 10);
      await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor: sourceActor, token: sourceToken()?.document }),
        content: "<p><strong>Укус.</strong> Пудж впивается в уже раненую цель и восстанавливает <strong>10 хитов</strong>.</p>"
      });
    }
  }
  return;
}

if (/Гниение/.test(sourceName)) {
  const active = !sourceActor.getFlag("world", "pudgeRotActive");
  await sourceActor.setFlag("world", "pudgeRotActive", active);
  if (active) {
    await applyEffect(sourceActor, {
      name: "Гниение включено",
      flag: "pudgeRotAura",
      statuses: [],
      duration: {},
      description: "<p>Аура гниения включена. В начале хода Пуджа враги в 15 футах проходят спасбросок Телосложения СЛ 19 против некротического урона и отравления. Сам Пудж получает 9 некротического урона, который не снижается Щитом плоти.</p>"
    });
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: sourceActor, token: sourceToken()?.document }), content: "<p><strong>Гниение включено.</strong></p>" });
  } else {
    const effects = actorEffects(sourceActor).filter((effect) => effect.getFlag?.("world", "pudgeRotAura"));
    if (effects.length) await sourceActor.deleteEmbeddedDocuments("ActiveEffect", effects.map((effect) => effect.id));
    await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: sourceActor, token: sourceToken()?.document }), content: "<p><strong>Гниение выключено.</strong></p>" });
  }
  return;
}

if (/Расчленение/.test(sourceName)) {
  for (const target of failedTargets()) {
    const initial = await rollParts([{ formula: "5d10", type: "piercing" }, { formula: "5d10", type: "necrotic" }], "Расчленение: начальный урон");
    await applyDamage(target, initial.details, initial.total);
    await applyEffect(target.actor, {
      name: "Расчленяется Пуджем",
      flag: "pudgeDismembered",
      statuses: ["grappled", "stunned"],
      duration: { rounds: 1, turns: 1 },
      world: { pudgeDismemberSource: sourceActor.uuid },
      description: "<p>Пудж удерживает цель крюками и рвёт её плоть. Цель схвачена и оглушена до начала следующего хода Пуджа. Она не совершает проверок освобождения. Если Пудж будет оглушён, парализован, обездвижен сознанием или потеряет возможность удерживать цель, эффект прерывается.</p>"
    });
    await applyEffect(sourceActor, {
      name: "Канал: Расчленение",
      flag: "pudgeDismemberChannel",
      statuses: [],
