function setUses(item, max, recovery) {
  item.system.uses = { spent: 0, max: String(max), recovery };
}

function fixActivityId(activity) {
  const id = foundry.utils.randomID(16);
  activity._id = id;
  return id;
}

function finishSingleActivity(item, source, activityName, uses = null) {
  const activity = activityValues(source.system.activities)[0];
  const id = fixActivityId(activity);
  activity.name = activityName;
  activity.img = item.img;
  if (uses) activity.uses = uses;
  item.system.activities = { [id]: activity };
}

function addAttackActivity(item, { activityName, activation = "action", reach = 5, range = null, actionType = "mwak", ability = "str", damageParts = [] }) {
  const source = clone(item);
  source.system.actionType = actionType;
  source.system.activation = { type: activation, cost: 1, condition: "" };
  source.system.attack = { bonus: "", flat: false };
  source.system.ability = ability;
  source.system.range = range
    ? { value: range, long: range, units: "ft" }
    : { value: null, long: null, reach, units: "ft" };
  source.system.target = { value: 1, type: "creature", units: "", prompt: true };
  source.system.damage = { parts: damageParts };
  CONFIG.DND5E.activityTypes.attack.documentClass.createInitialActivity(source, { offset: 0 });
  finishSingleActivity(item, source, activityName);
}

function addSaveActivity(item, { activityName, activation = "action", range = 60, ability = "con", prompt = true, damageParts = [] }) {
  const source = clone(item);
  source.system.actionType = "save";
  source.system.activation = { type: activation, cost: 1, condition: "" };
  source.system.range = { value: range, units: "ft" };
  source.system.target = { value: null, type: "creature", units: "", prompt };
  source.system.save = { ability, dc: SAVE_DC, scaling: "flat" };
  source.system.damage = { parts: damageParts };
  CONFIG.DND5E.activityTypes.save.documentClass.createInitialActivity(source, { offset: 0 });
  finishSingleActivity(item, source, activityName);
}

function addUtilityActivity(item, { activityName, activation = "action", uses = null }) {
  const source = clone(item);
  source.system.activation = { type: activation, cost: 1, condition: "" };
  CONFIG.DND5E.activityTypes.utility.documentClass.createInitialActivity(source, { offset: 0 });
  finishSingleActivity(item, source, activityName, uses);
}

