async function upsertEngine(dryRun, log) {
  const existing = game.macros.find((entry) => entry.name === ENGINE_NAME);
  if (dryRun) return { action: existing ? "update" : "create", name: ENGINE_NAME };
  const data = {
    name: ENGINE_NAME,
    type: "script",
    img: "icons/commodities/hooks/hook-meat-red.webp",
    scope: "global",
    command: PUDGE_ENGINE,
    ownership: { default: CONST.DOCUMENT_OWNERSHIP_LEVELS.OWNER },
    flags: { "ai-patcher": { bundleId: BUNDLE_ID }, world: { pudgeButcher: true } }
  };
  if (existing) {
    await existing.update(data);
    log(`Обновлена обработка ${ENGINE_NAME}`);
    return { action: "updated", uuid: existing.uuid };
  }
  const created = await Macro.create(data);
  log(`Создана обработка ${ENGINE_NAME}`);
  return { action: "created", uuid: created.uuid };
}

async function createOrUpdateJournal(folderId, actor, dryRun) {
  const existing = game.journal.find((entry) => entry.getFlag("ai-patcher", "bundleId") === BUNDLE_ID || entry.name === JOURNAL_NAME);
  if (dryRun) return { action: existing ? "update" : "create", type: "JournalEntry", name: JOURNAL_NAME };
  const data = {
    name: JOURNAL_NAME,
    folder: folderId,
    flags: { "ai-patcher": { bundleId: BUNDLE_ID, role: "pudge-handout" } },
    pages: [{
      name: "Пудж",
      type: "text",
      text: { format: CONST.JOURNAL_ENTRY_PAGE_FORMATS.HTML, content: journalContent(actor) }
    }]
  };
  if (existing) return existing.update(data);
  return JournalEntry.create(data);
}

export default async function patch({ dryRun = false, log = console.log, bundle } = {}) {
  if (game.system.id !== "dnd5e") throw new Error("Пудж создан для системы dnd5e.");

  const actorFolder = await getOrCreateFolder(FOLDER_NAME, "Actor");
  const journalFolder = await getOrCreateFolder(FOLDER_NAME, "JournalEntry");
  const actorData = baseActorData(bundle);
  actorData.folder = actorFolder.id;
  const itemData = buildItems();

  const existing = game.actors.find((actor) =>
    actor.getFlag("ai-patcher", "bundleId") === BUNDLE_ID ||
    actor.getFlag("world", "pudgeButcher") ||
    /Пудж, Мясник Междумирья/i.test(actor.name ?? "")
  );

  if (dryRun) {
    return {
      action: existing ? "update actor and replace Pudge items" : "create actor",
      actor: ACTOR_NAME,
      cr: 16,
      items: itemData.map((item) => item.name),
      avatar: asset(bundle, AVATAR),
      token: asset(bundle, TOKEN)
    };
  }

  await upsertEngine(false, log);

  let actor = existing;
  if (actor) {
    log(`Обновление босса: ${actor.name}`);
    await actor.update(actorData);
    const oldItems = actor.items.filter((item) => item.getFlag("ai-patcher", "bundleId") === BUNDLE_ID || item.getFlag("world", "pudgeButcher"));
    if (oldItems.length) await actor.deleteEmbeddedDocuments("Item", oldItems.map((item) => item.id));
    await actor.createEmbeddedDocuments("Item", itemData);
  } else {
    log(`Создание босса: ${ACTOR_NAME}`);
    actorData.items = itemData;
    actor = await Actor.create(actorData);
  }

  if (!actor) throw new Error("Не удалось создать Пуджа: Foundry не вернул документ Actor.");
  await actor.setFlag("ai-patcher", "bundleId", BUNDLE_ID);
  await actor.setFlag("world", "pudgeButcher", true);
  await actor.setFlag("world", "pudgeVersion", VERSION);
  await createOrUpdateJournal(journalFolder.id, actor, false);

  return {
    actor: actor.uuid,
    name: actor.name,
    cr: actor.system.details.cr,
    itemCount: actor.items.size,
    avatar: actor.img,
    token: actor.prototypeToken.texture.src,
    version: VERSION
  };
}
